const rateLimit = require('express-rate-limit');

const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: { error: 'Too many requests, please try again later.' },
  standardHeaders: true,
  legacyHeaders: false,
});

app.use('/api', limiter);
```

---

### 2. **No Security Headers (OWASP A05:2021 – Security Misconfiguration)**
Missing security headers make your app vulnerable to XSS, clickjacking, and other attacks.

**Fix:**
```javascript
const helmet = require('helmet');

app.use(helmet());
```

---

### 3. **Missing Request Size Limit**
No limit on request body size allows **OWASP A04:2021 – Insecure Design** (DoS via large payloads).

**Fix:**
```javascript
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));
